INSERT INTO p_amb_section (id, act_id, name, line, icon, icon_svg, color, enabled, pinned, sort) VALUES ('b49e3b3abd8ed7e4', 'brand_speedin', 'Hair Skin & Nails', 'Any video for the Hair Skin & Nails strips: hair, skin, nails, the daily routine.', 'sparkles', '<path d="M11.017 2.814a1 1 0 0 1 1.966 0l1.051 5.558a2 2 0 0 0 1.594 1.594l5.558 1.051a1 1 0 0 1 0 1.966l-5.558 1.051a2 2 0 0 0-1.594 1.594l-1.051 5.558a1 1 0 0 1-1.966 0l-1.051-5.558a2 2 0 0 0-1.594-1.594l-5.558-1.051a1 1 0 0 1 0-1.966l5.558-1.051a2 2 0 0 0 1.594-1.594z"/><path d="M20 2v4"/><path d="M22 4h-4"/><circle cx="4" cy="20" r="2"/>', '#BE185D', 1, 0, 3);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('6825083f5b04f71a', 'brand_speedin', '5e56aec2dba4ba92', 1, 1, 1, 'live', 'Strip on the tongue in the car', 'The strip going on the tongue in the first second shows the whole product before anyone can scroll.', 'Anyone who drives to work, the gym or school pickup', 'Energy', 'Car selfie, show and tell', '["This little strip replaced my morning energy drink.", "Watch this. No water, no can, nothing.", "I used to buy one of these every single morning."]', '[{"label": "Open · 0 to 3s", "text": "Strip up to the lens, then onto your tongue. Say the first line."}, {"label": "Middle", "text": "Tongue out so we see it melting. Open the pack and show how many are inside. Hold up an old can or cup (no logo facing camera) and say what you used to spend time and sugar on."}, {"label": "Close", "text": "Pack next to your face. Say how your drive or morning felt, in your own words."}]', 'A strip held between two fingers right in front of the lens, then straight onto the tongue', 'Tongue out on camera with the strip half melted, then the can comes out next to the pack', '[{"brand": "NuStrips", "what": "Sit in your parked car, hold a Speedin Energy strip up to the camera, put it on your tongue and show it melting. Then hold up the energy drink can you used to buy and say why you stopped.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('9104ae47df0b8809', 'brand_speedin', '6825083f5b04f71a', 'upload', 'amb/brand_speedin/inspo-nustrips-car-can.mp4', 'NuStrips (inspiration)', 'Sit in your parked car, hold a Speedin Energy strip up to the camera, put it on your tongue and show it melting. Then hold up the energy drink can you used to buy and say why you stopped.', '5e56aec2dba4ba92', 1, 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('a14e4f4421470668', 'brand_speedin', '5e56aec2dba4ba92', 1, 2, 2, 'live', 'It is 2:56pm and I know exactly what happens next', 'Everyone knows the 3pm slump, so the clock alone makes people stop.', 'Office workers, work from home parents, students', 'Energy', 'Desk POV, 3pm slump', '["It is 2:56 and I already know how this goes.", "This is the exact moment my day falls apart.", "My 3pm used to mean a second coffee. Not anymore."]', '[{"label": "Open · 0 to 3s", "text": "Over the shoulder at your desk, then turn the laptop so we see the time."}, {"label": "Middle", "text": "Walk toward the coffee maker, stop, come back. Open a strip and put it on your tongue. Say it melts in about 30 seconds, no water."}, {"label": "Close", "text": "Back to typing, or out the door to the next thing. Say what your afternoon feels like now."}]', 'Laptop clock reading 2:56 PM, you looking tired at it', 'You walk to the coffee maker, stop, and turn back to the strip', '[{"brand": "The Patch Remedy", "what": "Film yourself at your desk right before 3pm, point at the clock on your laptop or phone, skip the coffee run and put a Speedin Energy strip on your tongue instead. Then get back to work.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('8b8a54067a891899', 'brand_speedin', 'a14e4f4421470668', 'upload', 'amb/brand_speedin/inspo-patchremedy-3pm-desk.mp4', 'The Patch Remedy (inspiration)', 'Film yourself at your desk right before 3pm, point at the clock on your laptop or phone, skip the coffee run and put a Speedin Energy strip on your tongue instead. Then get back to work.', '5e56aec2dba4ba92', 1, 1, 2);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('c825f507ba24fd37', 'brand_speedin', '740f18622a38461e', 1, 3, 3, 'live', 'If you are like me, your brain starts at night', 'A real messy night routine feels like the viewer''s own house.', 'Moms, busy parents, anyone whose mind races at night', 'Sleep', 'Night routine, voiceover', '["If you are like me, your brain turns on the second the kids are asleep.", "My night routine, the real one.", "I used to lie there for an hour. Here is what changed."]', '[{"label": "Open · 0 to 3s", "text": "Bathroom, brushing teeth, first line on screen."}, {"label": "Middle", "text": "Quick clips: kitchen, folding something, couch. Open a Sleep strip and put it on your tongue, say no water and no pills."}, {"label": "Close", "text": "Lights off, you walking to bed. Say how you feel when you wake up, in your words."}]', 'You in the bathroom mirror, toothbrush in mouth, tired face', 'The lights go off and the strip goes on in the dark kitchen or bedroom', '[{"brand": "Winks", "what": "Film your real night routine: brushing teeth, kitchen tidy, couch, then a Speedin Sleep strip on your tongue before lights out. Talk over it like you are telling a friend.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('9ecfc43ee60d6864', 'brand_speedin', 'c825f507ba24fd37', 'upload', 'amb/brand_speedin/inspo-winks-night-routine.mp4', 'Winks (inspiration)', 'Film your real night routine: brushing teeth, kitchen tidy, couch, then a Speedin Sleep strip on your tongue before lights out. Talk over it like you are telling a friend.', '740f18622a38461e', 1, 1, 3);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('e4eff557ff1d8d64', 'brand_speedin', 'b49e3b3abd8ed7e4', 1, 4, 4, 'live', 'My man''s logic: healthy means a mess', 'The mess is funny and makes the strip look easy without saying it.', 'Couples, roommates, siblings', 'Hair Skin & Nails', 'Two person skit', '["My man''s logic: healthy means scoops, spills and cleaning the whole kitchen.", "Every morning I watch this happen.", "He thinks this is the healthy way."]', '[{"label": "Open · 0 to 3s", "text": "Wide shot from the counter, partner mid mess, text on screen."}, {"label": "Middle", "text": "Shaking the shaker, powder on the counter, pill bottles. You step in with the pack."}, {"label": "Close", "text": "Strip on the tongue, partner shrugs, you both walk off. Leave the mess in frame."}]', 'Partner spilling powder everywhere, you watching with a mug, text on top', 'The hand off: you peel a strip and stick it on their tongue', '[{"brand": "Grüns", "what": "Two people, one kitchen. Your partner makes a huge mess with scoops, shakers and pill bottles while you sip your coffee and watch. Then you hand them a Speedin strip.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('dd9546eddea4df49', 'brand_speedin', 'e4eff557ff1d8d64', 'upload', 'amb/brand_speedin/inspo-gruns-couple-skit.mp4', 'Grüns (inspiration)', 'Two people, one kitchen. Your partner makes a huge mess with scoops, shakers and pill bottles while you sip your coffee and watch. Then you hand them a Speedin strip.', 'b49e3b3abd8ed7e4', 1, 1, 4);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('2671ba749b0a63cf', 'brand_speedin', '5e56aec2dba4ba92', 0, 0, 5, 'live', 'Feeling lazy? A day with the strip', 'Fast cuts of a real life show where the strip fits without a single word of selling.', 'Busy, active creators who can film 5 places in one day', 'Energy', 'Day in my life montage', '["Feeling lazy? Same. Here is my fix.", "Every place this strip came with me today.", "My whole day runs on one tiny strip."]', '[{"label": "Open · 0 to 3s", "text": "Close up of your hands opening the pouch, text on screen."}, {"label": "Middle", "text": "4 or 5 two second clips: car, kitchen, closet, gym, pack in your bag. Strip on the tongue in at least one."}, {"label": "Close", "text": "Pack in your bag or drawer, text: Perform. Recover. Glow."}]', 'Hands peeling the pouch open with text: Feeling lazy?', 'Strip goes on the tongue in the car, then a quick cut to you moving at the gym', '[{"brand": "NuStrips", "what": "Film quick clips of your real day: opening a Speedin Energy strip, putting it on in the car, the gym, getting dressed, the pack in your bag. Short clips, one line of text on each.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('e0d8f7b36d02ffb3', 'brand_speedin', '2671ba749b0a63cf', 'upload', 'amb/brand_speedin/inspo-nustrips-day-montage.mp4', 'NuStrips (inspiration)', 'Film quick clips of your real day: opening a Speedin Energy strip, putting it on in the car, the gym, getting dressed, the pack in your bag. Short clips, one line of text on each.', '5e56aec2dba4ba92', 1, 1, 5);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('e78d117f763faf0a', 'brand_speedin', '740f18622a38461e', 0, 0, 6, 'live', 'Night shift hack unlocked', 'Night shift workers instantly see themselves, and the uniform tells the story.', 'Nurses, shift workers, first responders', 'Sleep', 'Shift worker tip', '["Night shift people, this one is for you.", "Trying to sleep at 10am is a nightmare.", "I wish I had this when I started nights."]', '[{"label": "Open · 0 to 3s", "text": "Scrubs on, bedroom, first line with text on screen."}, {"label": "Middle", "text": "Talk about bright daylight and noise. Close the curtains, open a strip, put it on."}, {"label": "Close", "text": "Get into bed. Say how you feel when you wake up for your next shift."}]', 'You in scrubs pointing at the camera, text: Night shift hack unlocked', 'You close the blackout curtains and the strip goes on', '[{"brand": "Manta Sleep", "what": "In your scrubs or work uniform after a night shift, tell us how hard it is to sleep at 10am when the world is awake, then put a Speedin Sleep strip on before you get into bed.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('69b8f1b46c41bb41', 'brand_speedin', 'e78d117f763faf0a', 'upload', 'amb/brand_speedin/inspo-manta-night-nurse.mp4', 'Manta Sleep (inspiration)', 'In your scrubs or work uniform after a night shift, tell us how hard it is to sleep at 10am when the world is awake, then put a Speedin Sleep strip on before you get into bed.', '740f18622a38461e', 1, 1, 6);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('fd960ea189b614f5', 'brand_speedin', 'b49e3b3abd8ed7e4', 0, 0, 7, 'live', 'My hairstylist noticed before I did', 'Someone else noticing is more believable than you saying it.', 'Women who get regular cuts or color', 'Hair Skin & Nails', 'Stylist reaction, then talking head', '["My hairstylist asked me what I changed.", "When your stylist points it out, you know.", "I did not notice until she said it."]', '[{"label": "Open · 0 to 3s", "text": "Salon chair mirror selfie, stylist pointing at your hair."}, {"label": "Middle", "text": "At home, pack in hand. Say you take one Lemon strip every morning, no pills to swallow."}, {"label": "Close", "text": "Back to the salon clip or a hair flip. Say results are different for everyone and this is just you."}]', 'Salon mirror selfie, stylist holding up a section of your hair', 'Back home, you hold up the pack and say what you changed', '[{"brand": "MaryRuth''s", "what": "Film a mirror clip at the salon (or ask your stylist to point at your hair), then cut to you at home holding the Speedin Hair Skin & Nails pack and talking about taking it every day.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('4e6d76bbb22f7ce6', 'brand_speedin', 'fd960ea189b614f5', 'upload', 'amb/brand_speedin/inspo-maryruth-stylist-growth.mp4', 'MaryRuth''s (inspiration)', 'Film a mirror clip at the salon (or ask your stylist to point at your hair), then cut to you at home holding the Speedin Hair Skin & Nails pack and talking about taking it every day.', 'b49e3b3abd8ed7e4', 1, 1, 7);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('f7a902e011d50a5c', 'brand_speedin', '5e56aec2dba4ba92', 0, 0, 8, 'live', 'Two things that never leave my bag', 'The two things list makes people wait for the second item.', 'Gym goers, pickleball and golf players, coaches, runners', 'Energy', 'What''s in my bag', '["Two things that never leave my gym bag.", "I am at the court 5 days a week and these two always come with me.", "Thing one is obvious. Thing two is not."]', '[{"label": "Open · 0 to 3s", "text": "Phone low on the floor, you crouched over your bag holding your gear."}, {"label": "Middle", "text": "Put the gear down, pull out the Speedin pack, show a strip, put one on before you play."}, {"label": "Close", "text": "Toss the pack back in the bag and walk into your session."}]', 'Low angle, you holding your main piece of gear up to the lens', 'The second thing comes out and it is tiny', '[{"brand": "Infraredi", "what": "Crouch next to your gym bag, sports bag or work bag and say: two things that never leave my bag. Pull out your gear, then your Speedin Energy strips, and say when you use them.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('b45611df1a1f7951', 'brand_speedin', 'f7a902e011d50a5c', 'upload', 'amb/brand_speedin/inspo-infraredi-bag-two-things.mp4', 'Infraredi (inspiration)', 'Crouch next to your gym bag, sports bag or work bag and say: two things that never leave my bag. Pull out your gear, then your Speedin Energy strips, and say when you use them.', '5e56aec2dba4ba92', 1, 1, 8);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('958c38c9a236697e', 'brand_speedin', '740f18622a38461e', 0, 0, 9, 'live', 'Reply to a comment: what is actually in it?', 'Answering a real question feels helpful, and people stay for the answer.', 'Anyone, no face needed', 'Sleep', 'Comment reply, hands only', '["Replying to the comment asking how a strip even works.", "You asked what is in it, so here is the back of the pack.", "Yes, it really melts. Watch."]', '[{"label": "Open · 0 to 3s", "text": "Comment bubble on screen, pack in your hands."}, {"label": "Middle", "text": "Flip to the label, point at the key ingredients, peel a strip and show how thin it is."}, {"label": "Close", "text": "Strip on your fingertip next to the pack. Say: 30 strips, one a day."}]', 'Comment bubble on screen over your hands holding the pack', 'Close up on the label with your finger on the line that matters', '[{"brand": "Shameless Snacks", "what": "Reply to a real comment (like: wait, how does a strip work?) with the comment bubble on screen. Hands only: show the pack, flip it, point at the label, peel a strip.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('6bb466bc5eda219b', 'brand_speedin', '958c38c9a236697e', 'upload', 'amb/brand_speedin/inspo-shameless-comment-reply.mp4', 'Shameless Snacks (inspiration)', 'Reply to a real comment (like: wait, how does a strip work?) with the comment bubble on screen. Hands only: show the pack, flip it, point at the label, peel a strip.', '740f18622a38461e', 1, 1, 9);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('f9f117a83fa42bd3', 'brand_speedin', 'b49e3b3abd8ed7e4', 0, 0, 10, 'live', 'My hair routine, inside and out', 'The strip slides into a routine people already love watching.', 'Beauty and hair creators', 'Hair Skin & Nails', 'Hair routine GRWM', '["My hair routine this season.", "Outside steps, then the inside step most people skip.", "Everything I do for my hair, in order."]', '[{"label": "Open · 0 to 3s", "text": "Bathroom mirror, hands in your hair, text on screen."}, {"label": "Middle", "text": "Quick clips of your real products, then towel on, strip on the tongue."}, {"label": "Close", "text": "Finished hair, hair flip, pack in hand."}]', 'Hands in your hair at the mirror, text: hair routine', 'Towel on your head, strip on your tongue', '[{"brand": "Hairburst", "what": "Film your hair routine in the bathroom: scalp, wash, towel. End with your Speedin Hair Skin & Nails strip as the inside step, then the finished hair.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('9b9339df128c50b6', 'brand_speedin', 'f9f117a83fa42bd3', 'upload', 'amb/brand_speedin/inspo-hairburst-hair-routine.mp4', 'Hairburst (inspiration)', 'Film your hair routine in the bathroom: scalp, wash, towel. End with your Speedin Hair Skin & Nails strip as the inside step, then the finished hair.', 'b49e3b3abd8ed7e4', 1, 1, 10);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('1cb142842910df06', 'brand_speedin', '5e56aec2dba4ba92', 0, 0, 11, 'live', 'My old morning drink build vs one strip', 'Watching a long build makes one strip feel like a relief.', 'Coffee lovers, kitchen creators', 'Energy', 'Kitchen build, then the swap', '["This used to be my morning. Every step.", "First, two scoops. Then the frother. Then...", "I timed my old morning drink. Eight minutes."]', '[{"label": "Open · 0 to 3s", "text": "Wide kitchen shot, jars everywhere, first line."}, {"label": "Middle", "text": "Speed through the steps with a word on screen for each. Then stop."}, {"label": "Close", "text": "Peel a strip, put it on, grab your keys. You can still drink coffee for the taste, say the strip is your energy now."}]', 'Counter full of jars and a frother, you mid scoop', 'You stop halfway, push it all aside and pick up the strip', '[{"brand": "Everyday Dose", "what": "Film the full ritual of your old morning drink (scoops, frother, creamer, the mess), talking through every step. Then show your new morning: one Speedin Energy strip, done.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('42fc700702a407b4', 'brand_speedin', '1cb142842910df06', 'upload', 'amb/brand_speedin/inspo-dose-coffee-build.mp4', 'Everyday Dose (inspiration)', 'Film the full ritual of your old morning drink (scoops, frother, creamer, the mess), talking through every step. Then show your new morning: one Speedin Energy strip, done.', '5e56aec2dba4ba92', 1, 1, 11);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('01d36b86a161baec', 'brand_speedin', '740f18622a38461e', 0, 0, 12, 'live', 'My bag does not need to sound like a maraca', 'The rattle sound is a hook people hear before they see it.', 'Anyone, no face needed', 'Sleep', 'Hands only swap', '["My bag does not need to sound like a maraca every time I move.", "Listen to this.", "Swapping my whole pill situation for this."]', '[{"label": "Open · 0 to 3s", "text": "Shake the bag right at the mic. Text on screen."}, {"label": "Middle", "text": "Pull out each bottle and line them up. Slide the Speedin pack in."}, {"label": "Close", "text": "Shake the bag again: silence. Zip it up."}]', 'A purse being shaken, pill bottles rattling', 'Bottles come out, one flat pack goes in, bag is quiet', '[{"brand": "Emmafy", "what": "Shake your bag so we hear the pill bottles rattle, then swap them for the flat Speedin pack. Hands only, filmed in your car or at your desk.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('045b7ac429827bbe', 'brand_speedin', '01d36b86a161baec', 'upload', 'amb/brand_speedin/inspo-emmafy-bag-rattle.mp4', 'Emmafy (inspiration)', 'Shake your bag so we hear the pill bottles rattle, then swap them for the flat Speedin pack. Hands only, filmed in your car or at your desk.', '740f18622a38461e', 1, 1, 12);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('b215d0f7bed39c5f', 'brand_speedin', 'b49e3b3abd8ed7e4', 0, 0, 13, 'live', 'Supplement hacks have gone too far', 'Making fun of the old way makes the new way obvious in 20 seconds.', 'Anyone with a funny face and a cluttered cabinet', 'Hair Skin & Nails', 'Over the top before, simple after', '["Supplement routines have gone too far.", "This is my morning. Every morning.", "Or you could just do this."]', '[{"label": "Open · 0 to 3s", "text": "Extreme close up, handful of pills, text on screen."}, {"label": "Middle", "text": "Struggle: water glass, shaker, gummy jar. Keep it quick and silly."}, {"label": "Close", "text": "Text: or just one strip. Peel, place, smile."}]', 'Your face super close, too many pills in your hand, text: this has gone too far', 'Hard cut to calm you with one strip', '[{"brand": "Hostage Tape", "what": "Close up comedy: line up every pill bottle, powder, shaker and gummy jar you own and struggle through them. Then cut to you peeling one Speedin strip and smiling.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('2e270b92da1d7a70', 'brand_speedin', 'b215d0f7bed39c5f', 'upload', 'amb/brand_speedin/inspo-hostage-hacks-too-far.mp4', 'Hostage Tape (inspiration)', 'Close up comedy: line up every pill bottle, powder, shaker and gummy jar you own and struggle through them. Then cut to you peeling one Speedin strip and smiling.', 'b49e3b3abd8ed7e4', 1, 1, 13);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('5ad18515e5e2a574', 'brand_speedin', '5e56aec2dba4ba92', 0, 0, 14, 'live', 'Two games before noon and I am the one who needs the snack', 'Every sports parent knows the early Saturday, so the field alone makes them stop.', 'Sports parents, coaches, anyone with early weekend games', 'Energy', 'Sports Saturday vlog, voiceover', '["Saturday called for two soccer games and a football game.", "Sports parent life means I am at the field before the sun is.", "Everyone packs snacks for the kids. Nobody packs anything for the parents."]', '[{"label": "Open · 0 to 3s", "text": "Field at sunrise or the parking lot, phone in your hand, time showing on screen."}, {"label": "Middle", "text": "Quick clips: unloading the trunk, setting up chairs, then you leaning on the car with the strip going on your tongue. Say no water, no cup to hold while you cheer."}, {"label": "Close", "text": "You on the sideline cheering. Say what the rest of your Saturday felt like. Keep the pouch in your bag, away from kids."}]', 'Wide shot of an empty field at sunrise with the time on screen', 'Close up of the trunk: chairs, cooler, blankets, and the little Speedin pouch', '[{"brand": "Guava Family", "what": "Film your real sports Saturday as a voiceover: the field at 7am, the car trunk full of chairs and coolers, the sideline. Before the first whistle, you at the car with a Speedin Energy strip. The strip is for you, the grown up. Kids can be in the background playing but never with the pouch.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('72538ae721f0dc59', 'brand_speedin', '5ad18515e5e2a574', 'upload', 'amb/brand_speedin/inspo-guava-sideline-saturday.mp4', 'Guava Family (inspiration)', 'Film your real sports Saturday as a voiceover: the field at 7am, the car trunk full of chairs and coolers, the sideline. Before the first whistle, you at the car with a Speedin Energy strip. The strip is for you, the grown up. Kids can be in the background playing but never with the pouch.', '5e56aec2dba4ba92', 1, 1, 14);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('51090f331133ef2e', 'brand_speedin', '740f18622a38461e', 0, 0, 15, 'live', 'Me at 1am vs me now', 'One fixed wide shot of the whole bed shows the problem and the fix without anyone needing to explain it.', 'Anyone who tosses and turns, couples, people with a sense of humour', 'Sleep', 'Fixed wide shot of the whole bed from the foot, physical comedy', '["This was me every night at 1am.", "If you flip your pillow more than twice a night, this is for you.", "My partner filmed this. I had no idea I did this."]', '[{"label": "Open · 0 to 3s", "text": "Phone on the dresser or a shelf at the foot of the bed, whole bed in frame. You toss, turn, flip the pillow, kick a leg out. Caption with the time."}, {"label": "Middle", "text": "Cut to you sitting on the edge of the bed, Sleep strip on the tongue, melts in about 30 seconds, no water. Lights go low."}, {"label": "Close", "text": "Same wide shot: you lie down, roll over once and stay still. Say how mornings feel now, in your own words. Bedtime only, never before driving and never with a drink."}]', 'Flopping around the bed at 1am, covers flying', 'Same bed, same shot, now you barely move', '[{"brand": "Sonno", "what": "Prop your phone at the foot of the bed so the whole bed is in shot. Act out the old nights: flipping the pillow, kicking the covers off, rolling over again and again. Make it big and a bit silly. Then the new night: Sleep strip on the tongue, lights low, one roll over and you are still. Same shot, same bed, so the change is obvious.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('b921a05b479a2a3a', 'brand_speedin', '51090f331133ef2e', 'upload', 'amb/brand_speedin/inspo-sonno-bed-wide-flop.mp4', 'Sonno (inspiration)', 'Prop your phone at the foot of the bed so the whole bed is in shot. Act out the old nights: flipping the pillow, kicking the covers off, rolling over again and again. Make it big and a bit silly. Then the new night: Sleep strip on the tongue, lights low, one roll over and you are still. Same shot, same bed, so the change is obvious.', '740f18622a38461e', 1, 1, 15);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('f79fa1b9b43c99dc', 'brand_speedin', 'b49e3b3abd8ed7e4', 0, 0, 16, 'live', 'My nails in the sun', 'A close-up of real nails in sunlight is the proof people want, and it takes eight seconds to watch.', 'Nail lovers, people who post their sets, anyone growing their nails out', 'Hair Skin & Nails', 'Macro close-up of your hand in window sunlight, no talking', '["My nails in the sun, no filter.", "Day 60 of taking these.", "Nobody believes these are my real nails."]', '[{"label": "Open · 0 to 3s", "text": "Sunny window, pouch held in your hand, nails close to the lens."}, {"label": "Middle", "text": "Slow turn of the hand, then one shot of a strip going on your tongue, melts in about 30 seconds."}, {"label": "Close", "text": "Back to the nails in the light, one caption with how long you''ve been taking them. Say how they feel to you, never that they will grow for everyone."}]', 'Pouch in your hand in the sun, nails in focus', 'Slow hand turn, light catching the nails', '[{"brand": "Glowie", "what": "Hold your hand up in a sunny window and film your nails close, turning your hand slowly so the light catches them. No talking, just short captions. Open with the Speedin pouch in the same hand, then your nails, then a strip on the tongue. Keep it under 15 seconds. Natural nails or your usual set, both work.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('1cb8da95c3a91513', 'brand_speedin', 'f79fa1b9b43c99dc', 'upload', 'amb/brand_speedin/inspo-glowie-nails-sunlight.mp4', 'Glowie (inspiration)', 'Hold your hand up in a sunny window and film your nails close, turning your hand slowly so the light catches them. No talking, just short captions. Open with the Speedin pouch in the same hand, then your nails, then a strip on the tongue. Keep it under 15 seconds. Natural nails or your usual set, both work.', 'b49e3b3abd8ed7e4', 1, 1, 16);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('28a07f8a3e4c4390', 'brand_speedin', '5e56aec2dba4ba92', 0, 0, 17, 'live', 'Come on a run with me, and the halfway strip', 'A run you can follow along with feels like hanging out, and the halfway stop shows the strip in real life.', 'Runners, walkers, anyone training for a 5K', 'Energy', 'Run with me vlog, selfie style', '["Come on a run with me. Today''s game is finding everything yellow.", "Let''s go on a run together. First, fit check.", "Halfway through every long run I do the same thing."]', '[{"label": "Open · 0 to 3s", "text": "Phone in hand at home or by the front door. Quick fit check, then slide the Speedin pouch into your running belt."}, {"label": "Middle", "text": "Selfie clips while you run, plus quick shots of the yellow things you spot. Plain text for the miles, like mile 1, mile 2. At halfway, stop, strip on your tongue, say it melts in about 30 seconds and there is no bottle to carry."}, {"label": "Close", "text": "Finish the run and say how the second half felt, in your own words. No pop-up graphics or stickers, just you and the route."}]', 'You at home doing a fit check: come on a run with me', '"Okay, halfway. Three miles down, three to go" as you pull the pouch out of your belt', '[{"brand": "Honey Stinger", "what": "Film your own run with the phone in your hand, selfie style. Pick a game for the run, like spotting everything yellow on your route. Quick fit check at home, strip pouch in your running belt, then at the halfway point stop, put a Speedin Energy strip on your tongue and keep going. No water bottle needed.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('83c435abb3153375', 'brand_speedin', '28a07f8a3e4c4390', 'upload', 'amb/brand_speedin/inspo-honeystinger-color-run.mp4', 'Honey Stinger (inspiration)', 'Film your own run with the phone in your hand, selfie style. Pick a game for the run, like spotting everything yellow on your route. Quick fit check at home, strip pouch in your running belt, then at the halfway point stop, put a Speedin Energy strip on your tongue and keep going. No water bottle needed.', '5e56aec2dba4ba92', 1, 1, 17);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('296e639a11d48f68', 'brand_speedin', '740f18622a38461e', 0, 0, 18, 'live', 'My dog doesn''t care how I slept', 'Everyone with a dog knows the walk happens no matter how you slept. That makes the next morning the proof, not a promise.', 'Dog owners, early risers, anyone with a pet that wakes them up', 'Sleep', 'POV down at your feet walking the dog, pet in shot', '["My dog does not care how I slept.", "6am, and he''s already at the door.", "These walks used to feel like a punishment."]', '[{"label": "Open · 0 to 3s", "text": "Dark hallway or porch, phone pointed down: the dog at the door, the leash going on. Caption with the time."}, {"label": "Middle", "text": "Walking POV, your feet and the leash, the dog ahead. Cut to the night before: Sleep strip on the tongue at bedtime, melts in about 30 seconds."}, {"label": "Close", "text": "Sitting on the step, dog next to you. Say how the morning feels now, in your own words. Sleep strips at bedtime only."}]', 'Dark early morning, your dog already at the door', 'Sitting on the step with the dog, sun up, still awake and fine', '[{"brand": "Vessi", "what": "Film your morning dog walk from your own eyes: phone pointed down at your feet and the leash, the dog pulling ahead. Open with the dark early morning, then the walk, then a quick moment on the front step with your dog. Talk about how these early walks used to feel after a bad night, and how they feel now. The dog is the star; you are behind the camera.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('2298fe134277f02b', 'brand_speedin', '296e639a11d48f68', 'upload', 'amb/brand_speedin/inspo-vessi-dog-walk-pov.mp4', 'Vessi (inspiration)', 'Film your morning dog walk from your own eyes: phone pointed down at your feet and the leash, the dog pulling ahead. Open with the dark early morning, then the walk, then a quick moment on the front step with your dog. Talk about how these early walks used to feel after a bad night, and how they feel now. The dog is the star; you are behind the camera.', '740f18622a38461e', 1, 1, 18);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('0b6020f7e9571a6c', 'brand_speedin', 'b49e3b3abd8ed7e4', 0, 0, 19, 'live', 'Mirror check, 30 days before the wedding', 'A mirror selfie is how people already check themselves before a big day, so it feels like your camera roll, not an ad.', 'Brides, bridesmaids, anyone with a big date coming up', 'Hair Skin & Nails', 'Mirror selfie and full-length outfit check', '["30 days until the wedding. Mirror check.", "If you have a big day coming up, start now.", "Getting ready for my best friend''s wedding."]', '[{"label": "Open · 0 to 3s", "text": "Bathroom mirror, phone visible, caption with the countdown. Hold the pouch up to the mirror."}, {"label": "Middle", "text": "Strip on the tongue in the mirror, melts in about 30 seconds, no water. Quick close shots of hair and skin in daylight."}, {"label": "Close", "text": "Full-length mirror on the day, full outfit. Say how your hair, skin and nails feel to you, in your own words. No promises of results by a date."}]', 'Bathroom mirror, phone in hand, caption: 30 days until the wedding', 'Full-length mirror on the day, outfit and hair done', '[{"brand": "Duradry", "what": "Film in your bathroom mirror with the phone visible, then in a full-length mirror for an outfit check. Use a real date you are getting ready for: a wedding, a trip, a big birthday. Show the Hair Skin & Nails strip as part of getting ready, then the full outfit, hair and skin in the mirror. Phone stays in your hand the whole time.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('e2bc7633f170f743', 'brand_speedin', '0b6020f7e9571a6c', 'upload', 'amb/brand_speedin/inspo-duradry-mirror-check.mp4', 'Duradry (inspiration)', 'Film in your bathroom mirror with the phone visible, then in a full-length mirror for an outfit check. Use a real date you are getting ready for: a wedding, a trip, a big birthday. Show the Hair Skin & Nails strip as part of getting ready, then the full outfit, hair and skin in the mirror. Phone stays in your hand the whole time.', 'b49e3b3abd8ed7e4', 1, 1, 19);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('ef4f42eba4370d83', 'brand_speedin', '5e56aec2dba4ba92', 0, 0, 20, 'live', 'By hour eight of my shift, my water bottle is still full', 'Someone with a nonstop job saying "I don''t have time to stop and drink something" explains no water better than we can.', 'Nurses, teachers, servers, retail and warehouse workers, anyone on long shifts', 'Energy', 'Get ready for my shift vlog, talking head', '["By hour eight of my shift, my coffee is cold and my water bottle is still full.", "Twelve hour shifts will humble you.", "Nobody at my job has time to stop and drink anything."]', '[{"label": "Open · 0 to 3s", "text": "Phone propped on the counter, you already dressed for work, talking straight to camera."}, {"label": "Middle", "text": "Quick clips of getting ready and packing your work bag with the Speedin pouch. Then a selfie clip at work or on your break: strip on your tongue, melts in about 30 seconds, no water, back to it."}, {"label": "Close", "text": "Back home at the end of the shift, hold up the full water bottle and say how the day felt, in your own words. Never film patients, students or customers, and keep work badges and logos out of shot."}]', 'You in scrubs or uniform at the kitchen counter: by hour eight of my shift', 'Holding up your still-full water bottle at the end of the shift', '[{"brand": "DryWater", "what": "Film it on a real work day in your scrubs or uniform. Tell the truth about your job: you never get to stop, your coffee goes cold, your water bottle comes home full. Show getting ready, packing your work bag with the Speedin pouch, and a quick strip on the tongue in the hallway or break room. No water, no stopping. Works for nurses, teachers, servers, anyone who is on their feet all day.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('8725736ce91361ea', 'brand_speedin', 'ef4f42eba4370d83', 'upload', 'amb/brand_speedin/inspo-drywater-nurse-shift.mp4', 'DryWater (inspiration)', 'Film it on a real work day in your scrubs or uniform. Tell the truth about your job: you never get to stop, your coffee goes cold, your water bottle comes home full. Show getting ready, packing your work bag with the Speedin pouch, and a quick strip on the tongue in the hallway or break room. No water, no stopping. Works for nurses, teachers, servers, anyone who is on their feet all day.', '5e56aec2dba4ba92', 1, 1, 20);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('15fb385cce6b48b5', 'brand_speedin', '740f18622a38461e', 0, 0, 21, 'live', 'How I actually sleep on a red-eye', 'A red-eye or a long flight is the clearest sleep problem there is, and a strip with no water and no liquids is made for it.', 'Frequent flyers, people who travel for work, anyone with jet lag', 'Sleep', 'Propped phone, full body at an empty airport gate', '["How I actually sleep on a red-eye.", "Ten hour flight, and I''m going to sleep for most of it.", "My carry-on has no liquids and still has my sleep routine in it."]', '[{"label": "Open · 0 to 3s", "text": "Phone propped on a seat at the gate, full body in shot. Walk up, sit, unzip the bag and hold the pouch to the lens."}, {"label": "Middle", "text": "On the plane, window seat, once you are settled for the night: Sleep strip on the tongue, melts in about 30 seconds, no water. Hood up or eye mask on."}, {"label": "Close", "text": "Next morning walking out of arrivals, say how you feel in your own words. Never film crew or other passengers'' faces, and never take it before you drive."}]', 'You walking up to the camera at an empty gate, travel outfit on', 'Walking out of arrivals the next morning, actually awake', '[{"brand": "Comfrt", "what": "Prop your phone on a seat at an empty gate and film yourself full body in your comfy travel outfit, walking up to the camera, sitting down, showing your carry-on. Show the Speedin pouch in your bag: no liquids, nothing to declare. Then on the plane, once you are settled for the night, a Sleep strip on the tongue. Land and show yourself walking out of arrivals awake.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('f1472c0cce10391a', 'brand_speedin', '15fb385cce6b48b5', 'upload', 'amb/brand_speedin/inspo-comfrt-airport-gate.mp4', 'Comfrt (inspiration)', 'Prop your phone on a seat at an empty gate and film yourself full body in your comfy travel outfit, walking up to the camera, sitting down, showing your carry-on. Show the Speedin pouch in your bag: no liquids, nothing to declare. Then on the plane, once you are settled for the night, a Sleep strip on the tongue. Land and show yourself walking out of arrivals awake.', '740f18622a38461e', 1, 1, 21);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('112902e5c5dc048d', 'brand_speedin', 'b49e3b3abd8ed7e4', 0, 0, 22, 'live', 'Week 1 to week 8, same window', 'The same angle every week lets people judge for themselves. No talking needed, the diary is the argument.', 'Anyone watching their hairline, part or shedding, patient creators who can film for 8 weeks', 'Hair Skin & Nails', 'Week by week progress diary, same angle, jump cuts', '["Week 1. Filming this every week so I can''t lie to myself.", "Same window, same light, eight weeks.", "I almost didn''t post week 1."]', '[{"label": "Open · 0 to 3s", "text": "Window light, head tilted to the lens, part or hairline in focus. Caption: week 1. Strip on the tongue."}, {"label": "Middle", "text": "Fast cuts: week 2, week 4, week 6, each the same shot. Same light, no filters, no new haircut in between."}, {"label": "Close", "text": "Week 8, then cut straight back to week 1. Say how your hair feels to you in your own words. Never say it regrows or treats hair loss."}]', 'Week 1 caption, close on your part or hairline in window light', 'Week 8, same spot, same light, fast cut back to week 1', '[{"brand": "Be Bodywise", "what": "Film the same shot once a week for eight weeks: same window, same light, head tilted to the camera to show your hairline or part. Label each clip with the week. Cut them together fast so people can watch the change for themselves. One quick shot of the strip in each week or just at the start.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('914e4fd6cd385db8', 'brand_speedin', '112902e5c5dc048d', 'upload', 'amb/brand_speedin/inspo-bodywise-week-diary.mp4', 'Be Bodywise (inspiration)', 'Film the same shot once a week for eight weeks: same window, same light, head tilted to the camera to show your hairline or part. Label each clip with the week. Cut them together fast so people can watch the change for themselves. One quick shot of the strip in each week or just at the start.', 'b49e3b3abd8ed7e4', 1, 1, 22);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('a10dc561a0434b67', 'brand_speedin', '5e56aec2dba4ba92', 0, 0, 23, 'live', 'I handed a strip to strangers at a festival', 'Strangers trying it for the first time is proof we can''t fake. Their surprise that it melts with no water does the explaining.', 'Outgoing creators who go to events, markets, games or races', 'Energy', 'Strangers try it at a crowded event, handheld', '["I handed out energy strips to strangers at a festival.", "Day three of this festival and everyone is dead. So I brought these.", "Watch his face when it melts."]', '[{"label": "Open · 0 to 3s", "text": "Handheld, crowd and noise behind. Hold the pouch up to an adult and ask, try a strip? Catch the strip going on their tongue."}, {"label": "Middle", "text": "Quick cuts between three or four people. Their first word, the look when it melts, someone saying no water? Keep every real reaction, even the funny ones."}, {"label": "Close", "text": "One person says how they feel a bit later, in their own words. End on you handing out the last strip. Adults only, and only people who agreed to be filmed."}]', 'A stranger''s face the second the strip goes on their tongue, crowd behind them', 'The "wait, it''s gone already?" reaction about 30 seconds later', '[{"brand": "Intake Breathing", "what": "Take the pouch somewhere busy: a festival, a tailgate, a market, a race finish. Ask adults if they want to try an energy strip. Film their face when it goes on the tongue and when they realise it is already gone. No script, just real first reactions. Only film people who say yes, and get their okay to post.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('5b7b5bd7a5b66d21', 'brand_speedin', 'a10dc561a0434b67', 'upload', 'amb/brand_speedin/inspo-intake-strangers-event.mp4', 'Intake Breathing (inspiration)', 'Take the pouch somewhere busy: a festival, a tailgate, a market, a race finish. Ask adults if they want to try an energy strip. Film their face when it goes on the tongue and when they realise it is already gone. No script, just real first reactions. Only film people who say yes, and get their okay to post.', '5e56aec2dba4ba92', 1, 1, 23);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('487cb8dcd450928d', 'brand_speedin', '740f18622a38461e', 0, 0, 24, 'live', 'My lights out routine in four steps', 'The room getting darker on every step is the feeling of winding down. The strip is just one of the steps, which is how it should feel.', 'Anyone with a busy mind at bedtime, readers, people trying to get off their phone', 'Sleep', 'Fixed close-up on the nightstand, lamp dims to dark, text only', '["Step 1: the phone goes face down.", "My lights out routine, four steps.", "How I get my brain to shut up at night."]', '[{"label": "Open · 0 to 3s", "text": "Phone propped on the nightstand, warm lamp on. Your hand turns your phone face down. Caption: step 1."}, {"label": "Middle", "text": "Each step a little darker: a few pages of a book, then a Sleep strip from the pouch onto the tongue, melts in about 30 seconds, no water. Captions only, no talking."}, {"label": "Close", "text": "Last step: lamp off, the shot goes dark. Final caption says how mornings feel now, in your own words. Bedtime only, never with a drink."}]', 'Lamp on, phone face down on the nightstand, caption: step 1', 'The last step is the lamp clicking off and the screen going dark', '[{"brand": "Loftie", "what": "Prop your phone on the nightstand so it sees the lamp, your hands and the pillow edge. No talking: put your steps on screen as short captions (phone away, book, Sleep strip, lights). Dim the lamp as you go so the shot gets darker step by step, and end in the dark. It works best with a warm lamp in a real bedroom at night.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('f309b946e6d817bb', 'brand_speedin', '487cb8dcd450928d', 'upload', 'amb/brand_speedin/inspo-loftie-nightstand-lights-out.mp4', 'Loftie (inspiration)', 'Prop your phone on the nightstand so it sees the lamp, your hands and the pillow edge. No talking: put your steps on screen as short captions (phone away, book, Sleep strip, lights). Dim the lamp as you go so the shot gets darker step by step, and end in the dark. It works best with a warm lamp in a real bedroom at night.', '740f18622a38461e', 1, 1, 24);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('fe7a486d04c72dca', 'brand_speedin', 'b49e3b3abd8ed7e4', 0, 0, 25, 'live', 'Hair check in the wind', 'Hair in the wind in real sun is the glow look people save. It shows hair and skin without anyone saying a word.', 'Creators near the beach or anywhere windy, travel creators, long hair', 'Hair Skin & Nails', 'Outdoor beach, hair in the wind, handheld in full sun', '["Hair check in the wind.", "My hair used to look so flat in photos.", "Beach hair, no products, just these."]', '[{"label": "Open · 0 to 3s", "text": "Handheld, sea or sky behind you, wind blowing your hair across the frame. Pouch in your hand."}, {"label": "Middle", "text": "Pouch set down in the sand or on a ledge for one close shot. Strip on the tongue, melts in about 30 seconds, no water."}, {"label": "Close", "text": "Back to your hair and skin in the sun. One caption with how it feels to you, in your own words. No before and after promises."}]', 'Hair whipping in the wind, sea behind you', 'The pouch set down in the sand, then back to your hair in the light', '[{"brand": "Cecred", "what": "Take it outside: a beach, a windy pier, a rooftop. Hold the phone up, let the wind do the work and film your hair moving in real sunlight. Show the pouch in your hand, set it in the sand or on a ledge for one shot, then a strip on the tongue. No talking, just a caption. The outdoor light is what makes it.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('5cb0d08f55198944', 'brand_speedin', 'fe7a486d04c72dca', 'upload', 'amb/brand_speedin/inspo-cecred-beach-wind.mp4', 'Cecred (inspiration)', 'Take it outside: a beach, a windy pier, a rooftop. Hold the phone up, let the wind do the work and film your hair moving in real sunlight. Show the pouch in your hand, set it in the sand or on a ledge for one shot, then a strip on the tongue. No talking, just a caption. The outdoor light is what makes it.', 'b49e3b3abd8ed7e4', 1, 1, 25);
