INSERT OR IGNORE INTO p_amb_brand (act_id, slug, live, display_name, submit_platform, submit_label) VALUES ('brand_speedin', 'speedin', 0, 'Speedin', 'TRYBE', 'Film this on TRYBE');
UPDATE p_amb_brand SET display_name='Speedin', intro='Speedin strips melt on your tongue in about 30 seconds. No pills, no water. Watch a few videos below, pick one, and make your version in your real day.', about='Supplement strips for adults that dissolve on the tongue: Energy, Sleep and Hair Skin & Nails, 30 strips a pack, or all three in the Complete Bundle.', audience='Busy adults who hate swallowing pills: early starts, gym people, shift workers, new parents, anyone fighting the 3pm slump or a racing mind at night.', accent='#121212', logo_url='https://tools.go-mobius-digital.com/angles/logos/speedin.png', submit_platform='TRYBE', submit_url=NULL, submit_label='Film this on TRYBE', show_inspo=1, checklist_json='{"do": [{"title": "Film it on your phone", "text": "Vertical, natural light, your real car, kitchen or bedroom."}, {"title": "Strip in the first 3 seconds", "text": "Held to the lens or going on your tongue. That shot does the explaining."}, {"title": "Use it for real first", "text": "Try it for a few days so what you say is how it felt to you."}], "say": ["How it felt to you (\"no jitters for me\"), never what it does for everyone.", "Sleep strips are for bedtime only. Never with a drink or before driving.", "Melts on the tongue in about 30 seconds, no water. 30-day money-back guarantee."], "skip": ["Cures, treats, fixes, doctor recommended or FDA approved.", "Prices or codes unless we send you one. Other brands by name.", "Kids, pregnancy or nursing. These strips are for adults."]}', rules_json='["A real Speedin pack and your real routine. No AI images or AI-made video.", "Supplements: never say it cures or treats anything. No \"FDA approved\".", "Energy: \"no jitters, no crash\" only as how it felt to you. Sleep: never with alcohol, never before driving.", "Adults only. No claims about kids or pregnancy.", "No other supplement or energy brands by name and no competitor packaging in shot.", "Prices and offers only if they are live on speedinusa.com the day you post."]', avoid_json='[{"title": "The pack held up to the camera with a list of ingredients", "why": "Nobody stops for it. Put the strip on your tongue in your real day instead."}, {"title": "A ring light in a bedroom with nothing happening", "why": "Film the moment you need it: the car at 6am, the desk at 3pm, the bed at night."}]', pdf_json='{"line1": "Speedin creators,", "line2": "here''s what to film.", "intro": "Our creator hub is a board of videos that worked for other brands. Pick one, make your version with a Speedin strip in your real day, film it today. Read the short checklist at the bottom first.", "cta": "Your creator hub", "note": "Opens right on your phone. No login, no app.", "steps": ["Open the hub and pick a video", "Make your version in your day", "Send it in"]}', board_mode='picked', updated_at=datetime('now') WHERE act_id='brand_speedin';
